package com.kjh.groupware.domain.approval;
import com.kjh.groupware.domain.approval.dto.*; import com.kjh.groupware.global.response.ApiResponse; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("${app.api-prefix:/api/v1}/bereavement-policies") @RequiredArgsConstructor public class BereavementPolicyController{private final BereavementPolicyService service;@GetMapping public ApiResponse<List<BereavementPolicyResponse>> list(){return ApiResponse.ok(service.list());}@GetMapping("/options") public ApiResponse<List<BereavementOptionResponse>> options(@RequestParam(required=false) java.time.LocalDate date){return ApiResponse.ok(service.options(date==null?java.time.LocalDate.now():date));}@PostMapping public ApiResponse<BereavementPolicyResponse> create(@Valid @RequestBody BereavementPolicyRequest r,HttpServletRequest h){return ApiResponse.ok(service.create(r,h.getRemoteAddr(),h.getHeader("User-Agent")));}@PutMapping("/{id}") public ApiResponse<BereavementPolicyResponse> update(@PathVariable Long id,@Valid @RequestBody BereavementPolicyRequest r,HttpServletRequest h){return ApiResponse.ok(service.update(id,r,h.getRemoteAddr(),h.getHeader("User-Agent")));}}
